code='''from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != bg]
    if not colors:
        return g
    fg = max(colors, key=lambda v: counts[v])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    # An intact frame is already a complete pattern; otherwise repair the lines.
    frame_broken = (any(grid[r][c] == bg for r in (r0, r1) for c in range(c0, c1 + 1)) or
                    any(grid[r][c] == bg for c in (c0, c1) for r in range(r0, r1 + 1)))
    if not frame_broken:
        return g
    # Complete spans on any row or column with at least three same-color marks.
    for r in range(h):
        inds = [c for c in range(w) if grid[r][c] == fg]
        if len(inds) >= 3:
            for c in range(inds[0], inds[-1] + 1):
                if g[r][c] == bg: g[r][c] = 2
    for c in range(w):
        inds = [r for r in range(h) if grid[r][c] == fg]
        if len(inds) >= 3:
            for r in range(inds[0], inds[-1] + 1):
                if g[r][c] == bg: g[r][c] = 2
    # Close the outer rectangular frame, including sides with only two clues.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if g[r][c] == bg: g[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if g[r][c] == bg: g[r][c] = 2
    return g
'''
